def lengthOfLongestSubstringKDistinct(s, k):
    if k == 0 or not s: return 0
    max_len = 0
    n = len(s)
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(s[j])
            if len(seen) <= k:
                max_len = max(max_len, j - i + 1)
            else:
                break
    return max_len

