def lengthOfLongestSubstringKDistinct(s, k):
    if k == 0 or not s:
        return 0
    counts = {}
    left = 0
    max_len = 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            counts[s[left]] -= 1
            if counts[s[left]] == 0:
                del counts[s[left]]
            left += 1
        max_len = max(max_len, right - left + 1)
    return max_len

